const Research=(()=>{
const catalog={agriculture:[['plow','Plow','Turn soil more efficiently.'],['irrigation','Irrigation','Bring water to thirsty crops.'],['rotation','Crop rotation','Keep fields healthy between harvests.'],['storage','Food preservation','Make each harvest go further.']],industry:[['wheel','Wheel','Move heavy loads more easily.'],['mill','Watermill','Use moving water to power work.'],['tools','Standard tools','Make dependable tools for workers.'],['guild','Craft guilds','Share useful techniques between towns.']],arms:[['shield','Reinforced shields','Protect soldiers with stronger equipment.'],['bow','Improved bows','Train and equip more effective archers.'],['stirrup','Stirrups','Help mounted troops stay steady.'],['fortification','Fortification plans','Improve military engineering.']]};
const kits={agriculture:{food:2,wood:2},industry:{wood:2,metal:2},arms:{metal:2,cloth:2}};
const applied={
mining:{name:'Better mining',icon:'⛏',image:'tools',building:'mine',cost:{money:30,wood:15,metal:10},turns:3,good:'metal',bonus:.4,description:'+40% metal from this mine cell.'},
farming:{name:'Field irrigation',icon:'🌾',image:'irrigation',building:'farm',cost:{money:25,wood:15,metal:5},turns:2,good:'food',bonus:.3,description:'+30% food from this farm cell.'},
forestry:{name:'Managed forestry',icon:'🌲',image:'wheel',building:'lumberyard',cost:{money:25,metal:8,food:10},turns:2,good:'wood',bonus:.35,description:'+35% wood from this lumber-camp cell.'},
weaving:{name:'Improved looms',icon:'🧵',image:'mill',building:'workshop',cost:{money:30,wood:12,metal:8},turns:3,good:'cloth',bonus:.4,description:'+40% cloth from this workshop cell.'},
housing:{name:'Better housing',icon:'🏘',image:'guild',building:'settlement',cost:{money:35,wood:25,cloth:10},turns:3,description:'+120 housing spaces and +8 local happiness.'},
health:{name:'Public health',icon:'💧',image:'storage',building:'settlement',cost:{money:30,food:15,cloth:15},turns:2,description:'+6 local happiness. Helps attract residents.'}
};
function plans(c,budget=c.funding){return Object.keys(catalog).map(key=>{const money=c.tech[key]>=4?0:budget*c.researchShares[key]/100,cost=Object.fromEntries(Object.entries(kits[key]).map(([k,n])=>[k,Math.ceil(n*money/12*10)/10]));return {key,money,cost};});}
function kit(c,spent=Math.min(c.funding,c.stock.money)){const total={};for(const p of plans(c,spent))for(const [k,n] of Object.entries(p.cost))if(n)total[k]=(total[k]||0)+n;return Object.fromEntries(Object.entries(total).map(([k,n])=>[k,Math.round(n*10)/10]));}
function allocate(s,id,values){if(s.phase!=='implement')throw Error('Allocate research during Implement.');if(!Society.shares(values,Object.keys(catalog)))throw Error('Research shares must be whole percentages totaling 100.');const c=s.countries[id];c.researchBank[c.focus]=c.progress;c.researchShares={...values};}
function fund(s,c,notes,foodBudget=Infinity){c.researchBank[c.focus]=c.progress;const schools=s.cells.filter(x=>x.country===c.id&&x.buildings.includes('school')).length,budget=Math.min(c.funding,c.stock.money);let spent=0,foodUsed=0;c.researchReport={turn:s.turn,fields:[]};for(const p of plans(c,budget)){if(p.money<=0)continue;const missing=Object.entries(p.cost).filter(([k,n])=>c.stock[k]+1e-8<n||k==='food'&&foodBudget-foodUsed+1e-8<n);if(missing.length){const reason='needs '+missing.map(([k,n])=>n+' '+k+(k==='food'?' within the research allocation':'')).join(', ');notes.push(`${c.name}: ${p.key} research paused — ${reason}. Its money stays in the treasury.`);c.researchReport.fields.push({key:p.key,spent:0,points:0,reason});continue;}c.stock.money-=p.money;Object.entries(p.cost).forEach(([k,n])=>c.stock[k]=Math.max(0,c.stock[k]-n));foodUsed+=p.cost.food||0;const points=p.money*.6*Society.researchRate(c,p.key)*(.65+c.literacy/100)+Math.min(3,schools)*c.researchShares[p.key]/100;c.researchBank[p.key]+=points;spent+=p.money;c.researchReport.fields.push({key:p.key,spent:p.money,points,reason:''});}c.progress=c.researchBank[c.focus];return spent;}
function reason(s,country,id,type){const c=s.countries[country],cell=s.cells[id],p=applied[type];if(!p||!cell?.land||cell.country!==country)return 'Choose your own land cell.';if(c.development)return 'Finish or cancel the current development project first.';if(cell.improvements.includes(type))return 'Already developed here.';if(p.building==='settlement'?!Civic.settlement(cell):!cell.buildings.includes(p.building))return p.building==='settlement'?'Choose a city or town.':'Needs '+Game.buildings[p.building].name.toLowerCase()+'.';if(c.developmentBudget<p.cost.money)return 'Ask Economy for a development allowance of at least '+p.cost.money+' money.';const missing=Object.entries(p.cost).filter(([k,n])=>c.stock[k]<n);if(missing.length)return 'Need '+missing.map(([k,n])=>(Math.ceil((n-c.stock[k])*10)/10)+' more '+k).join(', ')+'.';return '';}
function start(s,country,id,type){if(s.phase!=='implement')throw Error('Start development during Implement.');const error=reason(s,country,id,type);if(error)throw Error(error);const c=s.countries[country],p=applied[type];Object.entries(p.cost).forEach(([k,n])=>c.stock[k]-=n);c.developmentBudget-=p.cost.money;c.development={type,cell:id,remaining:p.turns};}
function cancel(s,country){if(s.phase!=='implement')throw Error('Cancel development during Implement.');const c=s.countries[country],d=c.development;if(!d)throw Error('No active development project.');const p=applied[d.type];Object.entries(p.cost).forEach(([k,n])=>c.stock[k]+=Math.floor(n*d.remaining/p.turns*10)/10);c.developmentBudget=Math.min(200,c.developmentBudget+Math.floor(p.cost.money*d.remaining/p.turns*10)/10);c.development=null;}
function develop(s,notes){for(const c of s.countries){const d=c.development;if(!d)continue;const cell=s.cells[d.cell],p=applied[d.type];if(cell.country!==c.id){notes.push(`${c.name}: ${p.name} was lost when its cell changed owners; committed resources were lost.`);c.development=null;continue;}d.remaining=Math.max(0,d.remaining-Society.workRate(c,d.type,true));if(d.remaining===0){if(!cell.improvements.includes(d.type))cell.improvements.push(d.type);notes.push(`${c.name} completed ${p.name} at ${cell.settlement||'cell '+cell.id}: ${p.description}`);c.development=null;}}}
function multiplier(cell,good){return 1+(cell.improvements||[]).reduce((n,k)=>n+(applied[k]?.good===good?applied[k].bonus:0),0);}
function upgrade(s){s.release='0.9.0';s.countries.forEach(c=>{c.developmentBudget=c.developmentBudget??60;c.development=c.development??null;c.literacy=c.literacy??35;c.researchBank=c.researchBank||{agriculture:0,industry:0,arms:0};c.researchBank[c.focus]=c.progress;c.researchShares=c.researchShares??Object.fromEntries(Object.keys(catalog).map(k=>[k,k===c.focus?100:0]));});return s;}
function focus(c,key){if(!catalog[key])throw Error('Choose a research field.');c.researchBank[c.focus]=c.progress;c.focus=key;c.progress=c.researchBank[key]||0;c.researchShares=Object.fromEntries(Object.keys(catalog).map(k=>[k,k===key?100:0]));}
function achievement(key,level){const a=catalog[key]?.[level];return a?{id:a[0],name:a[1],text:a[2],bonus:key==='agriculture'?'+15% food production':key==='industry'?'+15% wood, metal and cloth':'+10% military strength'}:null;}
function education(s,c,notes){const population=s.cells.filter(x=>x.country===c.id).reduce((n,x)=>n+x.population,0),school=Society.curricula[c.education],rate=school.rate,gain=school.learning,cost=population*rate,paid=Math.min(cost,c.stock.money);c.stock.money-=paid;const schools=s.cells.filter(x=>x.country===c.id&&x.buildings.includes('school')).length;c.literacy=Math.max(0,Math.min(100,c.literacy+(cost===0?0:paid/cost)*gain+Math.min(1,schools*.15)-(paid<cost?.7:0)));notes.push(`${c.name}: education cost ${paid.toFixed(1)}; learning level ${Math.round(c.literacy)}%.`);}
function finish(c,notes){c.researchBank[c.focus]=c.progress;for(const key of Object.keys(catalog)){const need={agriculture:40,industry:40,arms:45}[key]*(c.tech[key]+1);if(c.tech[key]<4&&c.researchBank[key]>=need){c.researchBank[key]-=need;c.tech[key]++;const a=achievement(key,c.tech[key]-1);notes.push(`${c.name} discovered ${a.name}: ${a.bonus}.`);}if(c.tech[key]>=4)c.researchBank[key]=0;}c.progress=c.researchBank[c.focus];}
function validate(s){for(const c of s.countries){const d=c.development;if(c.researchReport&&(!Number.isInteger(c.researchReport.turn)||c.researchReport.turn<1||c.researchReport.turn>s.turn||!Array.isArray(c.researchReport.fields)||c.researchReport.fields.length>3||c.researchReport.fields.some(f=>!Object.hasOwn(catalog,f.key)||!Number.isFinite(f.spent)||f.spent<0||f.spent>100||!Number.isFinite(f.points)||f.points<0||f.points>1000||typeof f.reason!=='string'||f.reason.length>500)))throw Error('Invalid research report.');if(!Society.shares(c.researchShares,Object.keys(catalog)))throw Error('Invalid research allocation.');if(!Number.isFinite(c.developmentBudget)||c.developmentBudget<0||c.developmentBudget>200)throw Error('Invalid development allowance.');if(d&&(!Object.hasOwn(applied,d.type)||!Number.isInteger(d.cell)||!s.cells[d.cell]?.land||!Number.isFinite(d.remaining)||d.remaining<=0||d.remaining>applied[d.type].turns))throw Error('Invalid development project.');if(!Number.isFinite(c.literacy)||c.literacy<0||c.literacy>100||!c.researchBank||Object.keys(catalog).some(k=>!Number.isFinite(c.researchBank[k])||c.researchBank[k]<0))throw Error('Invalid education or research progress.');}}
return {catalog,applied,kits,plans,allocate,kit,fund,reason,start,cancel,develop,multiplier,upgrade,focus,achievement,education,finish,validate};})();
